.searchbox{position:relative;flex:1;min-width:240px;max-width:520px}
.searchbox input{
  width:100%;padding:13px 46px 13px 16px;border-radius:16px;border:1px solid var(--line);
  background:rgba(0,0,0,.22);color:var(--ink);font-family:inherit;font-size:1rem;outline:none;transition:.2s;
}
.searchbox input:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(255,209,102,.18)}
.searchbox .sicon{position:absolute;right:14px;top:50%;transform:translateY(-50%);opacity:.7;pointer-events:none}
.suggest{position:absolute;top:calc(100% + 6px);left:0;right:0;background:#101826f2;backdrop-filter:blur(14px);
  border:1px solid var(--line);border-radius:16px;overflow:hidden;z-index:60;box-shadow:var(--shadow);display:none}
.suggest.show{display:block}
.suggest .row{display:flex;justify-content:space-between;align-items:center;padding:11px 16px;cursor:pointer;gap:10px}
.suggest .row:hover,.suggest .row.hl{background:rgba(255,255,255,.08)}
.suggest .row b{font-weight:700}
.suggest .row small{color:var(--muted);font-size:.78rem}
.suggest .none{padding:14px 16px;color:var(--muted);font-size:.9rem}

/* ── views ── */
.view{display:none;animation:rise .45s ease}
.view.on{display:block}
@keyframes rise{from{opacity:0;transform:translateY(14px)}to{opacity:1;transform:none}}

/* ── home ── */
.heroq{text-align:right;margin:10px 0 26px}
.heroq h1{font-size:clamp(1.5rem,4.2vw,2.3rem);font-weight:900;letter-spacing:-.5px;line-height:1.45}
.heroq h1 .hl{color:var(--accent)}
.heroq p{color:var(--muted);font-size:.98rem;margin-top:6px}
.chips{display:flex;gap:10px;flex-wrap:wrap;margin:18px 0 26px}
.chip{border:1px solid var(--line);background:var(--card);padding:8px 16px;border-radius:999px;cursor:pointer;font-size:.9rem;font-weight:600;transition:.2s;min-height:40px}
.chip:hover{background:var(--card2);border-color:var(--accent);transform:translateY(-2px)}
h2.sec{font-size:1.08rem;font-weight:800;margin:26px 0 4px;display:flex;align-items:center;gap:10px}
h2.sec::after{content:"";flex:1;height:1px;background:var(--line)}
.hint{color:var(--muted);font-size:.82rem;margin-bottom:14px}

.board{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:12px}
.cel{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:14px 14px 12px;cursor:pointer;transition:.22s;position:relative;overflow:hidden}
.cel:hover{background:var(--card2);transform:translateY(-3px);box-shadow:var(--shadow)}
.cel .nm{font-weight:800;font-size:.95rem}
.cel .pv{color:var(--muted);font-size:.72rem;margin-bottom:8px}
.cel .tp{font-size:1.55rem;font-weight:900;letter-spacing:-1px;line-height:1.2}
.cel .wx{display:flex;align-items:center;justify-content:space-between}
.cel .wx svg{width:36px;height:36px;opacity:.95}
.cel .ds{font-size:.72rem;color:var(--muted);margin-top:2px}
.cel .sk{position:absolute;inset:0;background:linear-gradient(90deg,transparent 60%,rgba(255,255,255,.06));pointer-events:none}

.provrow{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:14px}
select.prov{font-family:inherit;background:rgba(0,0,0,.25);color:var(--ink);border:1px solid var(--line);
  border-radius:14px;padding:10px 14px;font-size:.92rem;outline:none;cursor:pointer;min-height:44px}
select.prov option{background:#101826}

/* ── city page ── */
.backbar{display:flex;align-items:center;gap:12px;margin-bottom:14px;flex-wrap:wrap}
.hero{
  background:linear-gradient(140deg,rgba(255,255,255,.10),rgba(255,255,255,.03));
  border:1px solid var(--line);border-radius:var(--r);padding:26px 26px 22px;box-shadow:var(--shadow);position:relative;overflow:hidden;
}
.hero::before{content:"";position:absolute;inset-inline-start:-80px;top:-110px;width:340px;height:340px;border-radius:50%;
  background:radial-gradient(circle,rgba(255,209,102,.16),transparent 70%);pointer-events:none}
.hero .grid{display:grid;grid-template-columns:minmax(220px,1fr) 2fr;gap:24px;align-items:center}
.bigT{font-size:clamp(3.6rem,10vw,5.4rem);font-weight:900;letter-spacing:-3px;line-height:1;text-shadow:0 6px 30px rgba(0,0,0,.3)}
.bigT sup{font-size:.32em;font-weight:700;vertical-align:top;letter-spacing:0}
.nowmeta{display:flex;flex-direction:column;gap:4px}
.nowmeta .desc{font-size:1.15rem;font-weight:800;color:var(--accent)}
.nowmeta .sub{color:var(--muted);font-size:.88rem}
.bigIco{width:96px;height:96px;margin-bottom:8px;filter:drop-shadow(0 8px 22px rgba(0,0,0,.35));animation:floaty 7s ease-in-out infinite}
@keyframes floaty{50%{transform:translateY(-7px)}}
.hstat{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:10px}
.hs{background:rgba(0,0,0,.18);border:1px solid var(--line);border-radius:14px;padding:10px 14px}
.hs .k{font-size:.72rem;color:var(--muted)}
.hs .v{font-size:1.02rem;font-weight:800;margin-top:1px}
.hs .v small{font-weight:500;font-size:.72rem;color:var(--muted)}
.windarrow{display:inline-block;transition:transform .8s ease}

.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:12px;margin-top:14px}
.mt{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:16px;transition:.2s}
.mt:hover{background:var(--card2)}
.mt .ic{font-size:1.05rem;margin-bottom:6px;opacity:.9;display:flex;align-items:center;gap:8px;color:var(--muted);font-weight:700;font-size:.78rem}
.mt .v{font-size:1.25rem;font-weight:900}
.mt .v small{font-size:.72rem;font-weight:600;color:var(--muted)}
.mt .n{font-size:.75rem;color:var(--muted);margin-top:2px}
.bar{height:6px;border-radius:4px;background:rgba(255,255,255,.12);margin-top:8px;overflow:hidden}
.bar i{display:block;height:100%;border-radius:4px;background:linear-gradient(90deg,#7dd3fc,var(--accent));transition:width .8s ease}

/* daily */
.days{display:grid;grid-template-columns:repeat(7,1fr);gap:10px;margin-top:10px}
.dyc{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:13px 8px;text-align:center;cursor:pointer;transition:.2s;min-height:44px}
.dyc:hover{background:var(--card2);transform:translateY(-3px)}
.dyc.sel{border-color:var(--accent);background:rgba(255,209,102,.10)}
.dyc .d{font-size:.8rem;font-weight:800}
.dyc .dt{font-size:.68rem;color:var(--muted)}
.dyc svg{width:42px;height:42px;margin:6px 0}
.dyc .hi{font-weight:900;font-size:.95rem}
.dyc .lo{color:var(--muted);font-size:.8rem}
.rangebar{height:4px;border-radius:2px;background:rgba(255,255,255,.12);margin:7px 6px 0;position:relative}
.rangebar i{position:absolute;height:100%;border-radius:2px;background:linear-gradient(90deg,#7dd3fc,#ffd166)}

/* hourly */
.tabs{display:flex;gap:8px;overflow-x:auto;padding-bottom:8px;margin-top:4px;scrollbar-width:thin}
.tab{white-space:nowrap;border:1px solid var(--line);background:var(--card);color:var(--ink);font-family:inherit;
  padding:8px 16px;border-radius:12px;cursor:pointer;font-size:.86rem;font-weight:700;min-height:42px}
.tab.sel{background:var(--accent);color:#20242e;border-color:transparent}
.hours{display:flex;gap:10px;overflow-x:auto;padding:12px 2px 16px;scrollbar-width:thin}
.hc{min-width:104px;background:var(--card);border:1px solid var(--line);border-radius:16px;padding:12px 8px;text-align:center;flex:0 0 auto;transition:.2s}
.hc:hover{background:var(--card2)}
.hc.now{border-color:var(--accent)}
.hc .h{font-size:.78rem;color:var(--muted);font-weight:700}
.hc svg{width:38px;height:38px;margin:4px 0}
.hc .t{font-weight:900;font-size:1.1rem}
.hc .f{font-size:.72rem;color:var(--muted)}
.hc .pop{font-size:.72rem;color:#7dd3fc;font-weight:800;margin-top:2px}
.hc .w{font-size:.7rem;color:var(--muted);margin-top:2px}

.chartwrap{background:var(--card);border:1px solid var(--line);border-radius:18px;padding:14px 10px 6px;margin-top:8px;overflow-x:auto}
table.htab{width:100%;border-collapse:collapse;margin-top:10px;font-size:.84rem}
table.htab th{color:var(--muted);font-weight:700;font-size:.74rem;padding:8px 6px;border-bottom:1px solid var(--line);white-space:nowrap}
table.htab td{padding:9px 6px;border-bottom:1px solid rgba(255,255,255,.06);text-align:center;white-space:nowrap}
table.htab tr:hover td{background:rgba(255,255,255,.05)}
table.htab td:first-child{font-weight:800}

.banner{display:flex;gap:10px;align-items:center;background:rgba(251,191,36,.12);border:1px solid rgba(251,191,36,.4);
  color:#ffe3a3;padding:10px 16px;border-radius:14px;margin-bottom:14px;font-size:.86rem}
footer{margin-top:44px;text-align:center;color:var(--muted);font-size:.76rem}
footer a{color:#9fc3e8}
.skel{background:linear-gradient(90deg,var(--card) 25%,var(--card2) 50%,var(--card) 75%);background-size:200% 100%;
  animation:sh 1.3s infinite;border-radius:16px;min-height:120px}
@keyframes sh{to{background-position:-200% 0}}
.err{background:rgba(248,113,113,.12);border:1px solid rgba(248,113,113,.4);color:#ffcaca;padding:16px 20px;border-radius:16px}

@media (max-width:860px){
  .hero .grid{grid-template-columns:1fr}
  .days{grid-template-columns:repeat(auto-fit,minmax(96px,1fr))}
}
@media (prefers-reduced-motion:reduce){
  *,*::before,*::after{animation:none!important;transition:none!important}
}
</style>
</head>
