const fs = require('fs');

const HTML = fs.readFileSync('/data/workspace/iran-weather/static/index.html', 'utf8');

// blastocyst: stub fetch to hit the real running server
const REAL = 'http://127.0.0.1:8734';
async function realFetch(url, opts) {
  // url is relative like /api/home ; map to real
  const full = url.startsWith('http') ? url : REAL + url;
  const r = await fetch(full, opts);
  const body = await r.text();
  return { ok: r.ok, status: r.status, json: async () => JSON.parse(body), text: async () => body };
}

const errors = [];
const dom = new JSDOM(HTML, {
  runScripts: 'dangerously',
  pretendToBeVisual: true,
  url: 'http://localhost/',
  beforeParse(window) {
    window.fetch = realFetch;
    window.localStorage = (() => {
      let s = {};
      return { getItem: k => (k in s ? s[k] : null), setItem: (k, v) => { s[k] = String(v); }, removeItem: k => { delete s[k]; } };
    })();
    window.scrollTo = () => {};
    window.requestAnimationFrame = cb => setTimeout(cb, 0);
    window.matchMedia = () => ({ matches: false, addListener: () => {}, removeListener: () => {} });
    window.addEventListener('error', e => errors.push('window error: ' + (e.error ? e.error.stack : e.message)));
  }
});

const { window } = dom;
window.onerror = (msg, src, line, col, err) => { errors.push('onerror: ' + msg + (err ? '\n' + err.stack : '')); };

(async () => {
  // wait for the page's own start() calls (loadHome, loadProvinces) to finish
  await new Promise(r => setTimeout(r, 6000));

  const doc = window.document;
  const board = doc.querySelector('#board');
  const chips = doc.querySelector('#chips');
  const provSel = doc.querySelector('#provSel');
  const provBoard = doc.querySelector('#provBoard');

  console.log('=== HOME ===');
  console.log('chips html length:', chips.innerHTML.length);
  console.log('chips sample:', chips.textContent.slice(0, 80));
  console.log('board cells:', board.querySelectorAll('.cel').length);
  console.log('board first cell text:', (board.querySelector('.cel') || {}).textContent || '(none)');
  console.log('provinces options:', provSel.options.length);
  console.log('provBoard cells:', provBoard.querySelectorAll('.cel').length);

  // Now simulate clicking a city (openCity) directly
  console.log('\n=== CITY (openCity 5 = شیراز) ===');
  try {
    await window.openCity(5);
    await new Promise(r => setTimeout(r, 1500));
    const cityBody = doc.querySelector('#cityBody');
    console.log('cityBody has hero:', !!cityBody.querySelector('.hero'));
    console.log('city name shown:', (cityBody.querySelector('.nowmeta .cn') || {}).textContent);
    console.log('day cards:', cityBody.querySelectorAll('.days .dyc').length);
    console.log('hour rows in table:', cityBody.querySelectorAll('#hourTable tbody tr').length);
    console.log('chart svg present:', !!cityBody.querySelector('#chartWrap svg'));
    console.log('big temp:', (cityBody.querySelector('.bigT') || {}).textContent);
    // test day select
    await window.selectDay(3);
    console.log('after selectDay(3) -> day detail metrics:', cityBody.querySelectorAll('#dayDetail .mt').length, '| chart still:', !!cityBody.querySelector('#chartWrap svg'));
