{"code":"import subprocess, os, struct, zlib

# ── 1. Create simple weather icon PNGs programmatically (no Pillow needed) ──
def make_png(w, h, rgba_data):
    """Minimal PNG from raw RGBA bytes."""
    def chunk(tag, data):
        c = tag + data
        return struct.pack('>I', len(data)) + c + struct.pack('>I', zlib.crc32(c) & 0xffffffff)
    sig = b'\x89PNG\r\n\x1a\n'
    ihdr = struct.pack('>IIBBBBB', w, h, 8, 6, 0, 0, 0)
    raw = b''
    for y in range(h):
        raw += b'\x00' + rgba_data[y*w*4:(y+1)*w*4]
    idat = zlib.compress(raw, 9)
    return sig + chunk(b'IHDR', ihdr) + chunk(b'IDAT', idat) + chunk(b'IEND', b'')

def icon_pixels(size):
    """Generate a sun+cloud icon as RGBA pixels."""
    px = bytearray(size*size*4)
    cx, cy, r = size//2, size//2, int(size*0.38)
    scx, scy, sr = int(size*0.42), int(size*0.40), int(size*0.18)
    def dist(x1,y1,x2,y2): return ((x1-x2)**2 + (y1-y2)**2)**0.5
    def sun_glow(x,y):
        d = dist(x,y,scx,scy)
        if d < sr*0.85: return (255,209,102,255)
        if d < sr*1.1: return (255,209,102,180)
        return None
    def cloud(x,y):
        # main blob
        if dist(x,y,cx,cy+int(size*0.15)) < r: return True
        # right blob
        if dist(x,y,cx+int(size*0.22),cy+int(size*0.08)) < r*0.7: return True
        # top blob
        if dist(x,y,cx-int(size*0.08),cy-int(size*0.08)) < r*0.75: return True
        return False
    for y in range(size):
        for x in range(size):
            i = (y*size+x)*4
            glow = sun_glow(x,y)
            if glow:
                px[i:i+4] = bytes(glow)
            elif cloud(x,y):
                # gradient from white to light blue
                t = (y - cy) / size
                rb = int(220 + t*20)
                gb = int(230 + t*15)
                bb = int(240 + t*10)
                px[i:i+4] = bytes([rb, gb, bb, 230])
            else:
                # transparent background
                px[i:i+4] = bytes([11, 58, 107, 0])
    return bytes(px)

sizes = {
    'mipmap-mdpi': 48,
    'mipmap-hdpi': 72,
    'mipmap-xhdpi': 96,
    'mipmap-xxhdpi': 144,
    'mipmap-xxxhdpi': 192,
}

for folder, sz in sizes.items():
    for suffix in ['ic_launcher.png', 'ic_launcher_round.png']:
        d = f'/data/workspace/iran-weather-android/res/{folder}'
        os.makedirs(d, exist_ok=True)
        p = f'{d}/{suffix}'
        rgba = icon_pixels(sz)
        with open(p, 'wb') as f:
            f.write(make_png(sz, sz, rgba))
        print(f"  {p} ({sz}x{sz})")

print("icons done")
"}

